package com.monitoring.agent

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.locks.ReentrantLock
import java.util.concurrent.atomic.AtomicInteger
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import java.security.MessageDigest

data class LogEntry(val timestamp: Long, val source: String, val message: String, val level: String)
data class AggregatedMetric(var count: AtomicInteger = AtomicInteger(0), var callbacks: MutableList<() -> Unit> = mutableListOf())

object MetricRegistry {
    private val metrics = ConcurrentHashMap<String, AggregatedMetric>()
    private val flushLock = ReentrantLock()
    private val pendingFlush = ConcurrentHashMap<String, Boolean>()

    fun getOrCreate(key: String): AggregatedMetric {
        return metrics.computeIfAbsent(key) { AggregatedMetric() }
    }

    fun registerCallback(key: String, cb: () -> Unit) {
        val metric = getOrCreate(key)
        metric.callbacks.add(cb)
    }

    fun incrementAndCheck(key: String, threshold: Int): Boolean {
        val metric = getOrCreate(key)
        val newVal = metric.count.incrementAndGet()
        if (newVal >= threshold) {
            triggerFlush(key, metric)
            return true
        }
        return false
    }

    private fun triggerFlush(key: String, metric: AggregatedMetric) {
        if (pendingFlush.putIfAbsent(key, true) == null) {
            flushLock.lock()
            try {
                metric.count.set(0)
                val callbacksCopy = metric.callbacks.toList()
                pendingFlush.remove(key)
                flushLock.unlock()
                for (cb in callbacksCopy) {
                    cb()
                }
            } catch (e: Exception) {
                pendingFlush.remove(key)
                if (flushLock.isHeldByCurrentThread) flushLock.unlock()
                throw e
            }
        }
    }
}

class LoggingAgent(private val hmacSecret: String, private val proxyTrustHeader: String = "X-Forwarded-For") {
    private val buffer = mutableListOf<LogEntry>()
    private val bufferLock = ReentrantLock()
    private val FLUSH_THRESHOLD = 5

    init {
        MetricRegistry.registerCallback("log.ingestion") {
            drainBuffer()
        }
    }

    fun validateRequest(headers: Map<String, String>, body: String): Boolean {
        val signature = headers["X-Signature"] ?: return false
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(hmacSecret.toByteArray(), "HmacSHA256"))
        val expected = Base64.getEncoder().encodeToString(mac.doFinal(body.toByteArray()))
        return MessageDigest.isEqual(expected.toByteArray(), signature.toByteArray())
    }

    fun ingest(headers: Map<String, String>, body: String): String {
        if (!validateRequest(headers, body)) {
            return "UNAUTHORIZED"
        }
        val source = headers[proxyTrustHeader] ?: "unknown"
        val entry = LogEntry(System.currentTimeMillis(), source, body, classifyLevel(body))
        bufferLock.lock()
        try {
            buffer.add(entry)
        } finally {
            bufferLock.unlock()
        }
        MetricRegistry.incrementAndCheck("log.ingestion", FLUSH_THRESHOLD)
        return "OK"
    }

    fun drainBuffer(): List<LogEntry> {
        bufferLock.lock()
        try {
            val drained = buffer.toList()
            buffer.clear()
            return drained
        } finally {
            bufferLock.unlock()
        }
    }

    private fun classifyLevel(msg: String): String {
        return when {
            msg.contains("ERROR", ignoreCase = true) -> "ERROR"
            msg.contains("WARN", ignoreCase = true) -> "WARN"
            else -> "INFO"
        }
    }
}

class ProxyHandler(private val agent: LoggingAgent) {
    fun handleRequest(rawHeaders: Map<String, String>, rawBody: String): String {
        val sanitizedHeaders = rawHeaders.mapValues { (_, v) -> v.trim() }
        return agent.ingest(sanitizedHeaders, rawBody)
    }
}

fun main() {
    val agent = LoggingAgent(hmacSecret = "s3cr3t-key-2024", proxyTrustHeader = "X-Real-IP")
    val handler = ProxyHandler(agent)
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(SecretKeySpec("s3cr3t-key-2024".toByteArray(), "HmacSHA256"))
    val testBody = "Test log ERROR message"
    val sig = Base64.getEncoder().encodeToString(mac.doFinal(testBody.toByteArray()))
    repeat(6) {
        val result = handler.handleRequest(
            mapOf("X-Real-IP" to "10.0.0.1", "X-Signature" to sig),
            testBody
        )
        println("Request $it: $result")
    }
    println("Final buffer size: ${agent.drainBuffer().size}")
}
